mutants.cherche:
Result<int> side(const Q4Candidate& sphere, Point point) noexcept {
  return center_side(CenterView(sphere), point);
}

mutants.remplace:
Result<int> side(const Q4Candidate& sphere, Point point) noexcept {
  auto value = center_side(CenterView(sphere), point);
  if (!value.ok()) return value.outcome();
  return -value.value();
}
